import type { PlanarState } from "../../src/features/tools/planar-kit/contract";
import { booleanRegions } from "../../src/features/tools/plane-overlap-curves/boolean";
import { circleRegion, polygonRegion } from "../../src/features/tools/plane-overlap-curves/geometry";
import { activateCurveMaterial, addCurveMaterial, addSquareForCircle, createCurveGeometry, createCurveOverlapState, curveMaterial, curveMaterials, extractCurveRegion, extractLeafSegments, reflectCurveMaterial, removeCurveMaterial, setCurveField, splitCurveMaterial } from "../../src/features/tools/plane-overlap-curves/model";
import { writeCurveMaterials } from "../../src/features/tools/plane-overlap-curves/state";

export function planeOverlapCurvesCases() {
  const initial = createCurveOverlapState();
  const cases: { label: string; accepted: boolean; scene: { toolId: string; contentVersion: string; payload: { title: string; initial: PlanarState } } }[] = [];
  const add = (label: string, state: PlanarState, accepted = true, title = "Real circular-arc regions", version = "plane-overlap-lesson-v4") => cases.push({ label, accepted, scene: { toolId: "plane-overlap", contentVersion: version, payload: { title, initial: state } } });
  const invalid = (label: string, change: (state: PlanarState) => void) => { const state = structuredClone(initial); change(state); add(label, state, false); };
  add("default", initial);
  for (let mode = 1; mode <= 4; mode++) add(`region-${mode}`, setCurveField(initial, "region", mode));
  add("reflected", reflectCurveMaterial(setCurveField(initial, "angle", 37)));
  add("radius-minimum", setCurveField(initial, "radius", 4)); add("radius-maximum", setCurveField(initial, "radius", 1600));
  const empty = removeCurveMaterial(removeCurveMaterial(initial)); add("empty", empty);
  let leaf = addCurveMaterial(empty, "leaf"); const ids = curveMaterials(leaf).map((material) => material.id);
  leaf = { ...leaf, params: { ...leaf.params, pairA: ids[0], pairB: ids[1] } }; add("leaf-split", extractLeafSegments(leaf));
  add("leaf-unequal", extractLeafSegments(setCurveField(activateCurveMaterial(leaf, ids[0]), "radius", 160)));
  add("outer-corners", extractCurveRegion(setCurveField(addSquareForCircle(initial, false), "region", 3)));
  add("inner-segments", extractCurveRegion(setCurveField(addSquareForCircle(initial, true), "region", 3)));
  add("arbitrary-chord", splitCurveMaterial(initial, { x: 100, y: 380 }, { x: 800, y: 310 }));
  const source = curveMaterial(initial, 1)!;
  for (const [label, x] of [["hole", 0], ["tangent-hole", 60]] as const) {
    const region = booleanRegions(circleRegion({ x: 0, y: 0 }, 120), circleRegion({ x, y: 0 }, 60), "difference")!;
    add(label, writeCurveMaterials({ ...initial, params: { ...initial.params, active: 1 } }, [curveMaterial(initial, 0)!, { ...source, kind: 2, region }]));
  }
  let full = empty;
  for (let index = 0; index < 16; index++) full = addCurveMaterial(full, "circle"); add("16-circles", full);
  let vertices = empty;
  const points = Array.from({ length: 12 }, (_, i) => ({ x: 400 + 100 * Math.cos(i * Math.PI / 6), y: 300 + 100 * Math.sin(i * Math.PI / 6) }));
  for (let index = 0; index < 16; index++) vertices = createCurveGeometry(vertices, "polygon", points)!; add("192-straight-vertices", vertices);
  add("all-observations", { ...initial, flags: Object.fromEntries(Object.keys(initial.flags).map((key) => [key, true])) });
  invalid("unknown-state-field", (state) => { Object.assign(state, { area: 42 }); });
  invalid("unknown-param", (state) => { state.params.extra = 1; });
  invalid("unknown-flag", (state) => { state.flags.extra = false; });
  invalid("unknown-point", (state) => { state.points.extra = { x: 0, y: 0 }; });
  invalid("missing-param", (state) => { delete state.params.region; });
  invalid("numeric-string", (state) => { Object.assign(state.params, { region: "1" }); });
  invalid("null-param", (state) => { Object.assign(state.params, { pairA: null }); });
  invalid("flag-string", (state) => { Object.assign(state.flags, { grid: "false" }); });
  invalid("orphan-pair", (state) => { state.params.pairA = 999; });
  invalid("same-pair", (state) => { state.params.pairB = state.params.pairA; });
  invalid("fractional-pair", (state) => { state.params.pairA = .5; });
  invalid("region-range", (state) => { state.params.region = 5; });
  invalid("phase", (state) => { state.phase = .5; });
  invalid("marks", (state) => { state.marks = ["computed-area"]; });
  invalid("noncanonical-id", (state) => { state.params["kind.01"] = 1; });
  invalid("next-id", (state) => { state.params.nextId = 1; });
  invalid("point-extra-key", (state) => { Object.assign(state.points["origin.1"], { z: 0 }); });
  invalid("point-outside-bound", (state) => { state.points["origin.1"].x = 4000.01; });
  invalid("support-radius-range", (state) => { state.params["radius.1.0"] = 3.99; });
  invalid("arc-off-circle", (state) => { state.points["vertex.1.0"].y = 1; });
  invalid("unknown-support", (state) => { state.params["arc.1.0"] = 2; });
  invalid("zero-arc-key", (state) => { state.params["arc.1.0"] = 0; });
  invalid("fractional-support", (state) => { state.params["arc.1.0"] = .5; });
  invalid("reverse-circle-half", (state) => { state.params["arc.1.1"] = -1; });
  invalid("duplicate-boundary-vertex", (state) => { state.points["vertex.0.1"] = { ...state.points["vertex.0.0"] }; });
  invalid("crossing-paper", (state) => { const a = state.points["vertex.0.0"]; state.points["vertex.0.0"] = state.points["vertex.0.1"]; state.points["vertex.0.1"] = a; });
  invalid("extra-loop", (state) => { state.params["count.1.1"] = 2; });
  const wrongHole = writeCurveMaterials(initial, [curveMaterial(initial, 0)!, { ...source, kind: 2, region: { loops: [...circleRegion({ x: 0, y: 0 }, 120).loops, ...circleRegion({ x: 0, y: 0 }, 60).loops] } }]);
  add("wrong-hole-orientation", wrongHole, false);
  const crossingLoops = writeCurveMaterials(initial, [curveMaterial(initial, 0)!, { ...source, kind: 2, region: { loops: [...circleRegion({ x: 0, y: 0 }, 120).loops, ...circleRegion({ x: 100, y: 0 }, 120).loops] } }]);
  add("overlapping-loops", crossingLoops, false);
  const straightPiece = { ...source, kind: 2 as const, region: polygonRegion([{ x: 0, y: 0 }, { x: 100, y: 0 }, { x: 100, y: 100 }, { x: 0, y: 100 }]) };
  add("straight-derived-piece", writeCurveMaterials(initial, [curveMaterial(initial, 0)!, straightPiece]));
  add("blank-title", initial, false, "\u00a0\u2003\ufeff");
  add("trimmed-title", initial, true, "\u2003\ufeffCurves\u00a0");
  add("80-utf16-title", initial, true, "圆".repeat(80)); add("81-utf16-title", initial, false, "圆".repeat(81));
  add("40-emoji-title", initial, true, "😀".repeat(40)); add("41-emoji-title", initial, false, "😀".repeat(41));
  add("v4-as-v3", initial, false, "Real curves", "plane-overlap-lesson-v3");
  const oldScene = { ...initial, sceneId: "33-concave" }; add("v3-scene-as-v4", oldScene, false);
  return cases;
}
